<template>
  <el-dialog :modelValue="modelValue" title="应用制作模板" width="min(820px, 96vw)" appendToBody :closeOnClickModal="false" :closeOnPressEscape="false" :showClose="!busy" :beforeClose="closeDialog" @update:modelValue="emit('update:modelValue', $event)">
    <div class="templateApply"><p>在目标项目中新建制作单元、画布和固定参考版本。原对象保留；本操作不会开始生成。</p><div v-if="error" ref="errorBox" class="errorText" role="alert" tabindex="-1">{{ error }}</div><div class="targetRow"><strong>目标项目</strong><workspacePicker v-model="directory" :disabled="busy" /><el-button :disabled="!directory || busy || loading" @click="loadTarget">刷新项目与模型</el-button></div><p class="projectPath">{{ directory || '请选择工作目录' }}</p><p v-if="loading" role="status">正在读取项目与已配置模型…</p>
      <p v-if="directory && !loading && !project && ready">此目录还没有制作记录。<el-button :disabled="busy" @click="createProject">创建制作记录</el-button></p>
      <section v-if="pending.length && !applied" class="pendingApplications"><h3>待完成的模板应用</h3><p>载入原草稿后，重新预览即可继续相同应用；已有副本会核对摘要。</p><el-button v-for="item in pending" :key="item.applicationId" :disabled="busy" @click="resume(item)">载入：{{ item.definition.title }} · {{ new Date(item.createdAt).toLocaleString() }}</el-button></section>
      <template v-if="project && input"><p v-if="resuming" class="hint">已载入中断前的固定输入。若需修改，请先创建新的独立应用。<el-button :disabled="busy" @click="startIndependent">改为新的独立应用</el-button></p><fieldset :disabled="busy || !!applied || resuming"><h3>{{ input.definition.title }}</h3><div class="inputGrid"><label v-for="item in input.definition.inputs" :key="item.key">{{ item.label }}{{ item.required ? '（必填）' : '' }}<textarea v-model="input.values[item.key]" :aria-label="item.label" rows="2" maxlength="10000" /></label></div><h3>映射实际渠道模型</h3><p class="hint">只列出已配置且媒体类型相符的模型。模型目录不代表连接、能力或价格已验收；每个位置都需要明确选择。</p><label v-for="slot in input.definition.modelSlots" :key="slot.key">{{ slot.label }} · {{ typeLabels[slot.mediaType] }}<select v-model="selections[slot.key]" :aria-label="slot.label + '模型映射'"><option value="">请选择模型或稍后配置</option><option value="deferred">稍后配置 · 应用后选择模型</option><option v-for="model in models.filter(model => model.type === slot.mediaType)" :key="JSON.stringify([model.providerId, model.modelId])" :value="JSON.stringify([model.providerId, model.modelId])">{{ model.providerLabel }} · {{ model.label }}（{{ model.modelId }}）</option></select><span>{{ slot.purpose }}</span><span v-if="slot.suggestedModelId">模板模型提示：{{ slot.suggestedModelId }} · 请核对目录后自行选择</span></label><h3 v-if="input.definition.mediaInputs.length">参考文件</h3><div v-for="item in input.definition.mediaInputs" :key="item.key" class="mediaBinding"><strong>{{ item.label }} · {{ item.required ? '必填' : '可选' }}</strong><p>{{ item.description }}</p><p>{{ input.mediaBindings.find(file => file.key === item.key)?.path || '尚未选择，将保留文字资料' }}</p><el-button @click="openFiles(item.key)">选择项目内{{ typeLabels[item.mediaType] }}</el-button><el-button v-if="input.mediaBindings.some(file => file.key === item.key)" @click="input.mediaBindings = input.mediaBindings.filter(file => file.key !== item.key)">移除所选文件</el-button></div></fieldset>
        <el-button v-if="!applied" :disabled="busy || loading || !ready" :loading="previewing" @click="previewApplication">{{ preview ? '重新预览应用内容' : '预览应用内容' }}</el-button><section v-if="preview" class="applicationPreview" aria-label="应用预览"><h3>将新增：{{ preview.title }}</h3><p>{{ preview.counts.shots }} 个镜头 · {{ preview.counts.assets }} 个素材 · {{ preview.counts.versions }} 个固定版本 · {{ preview.counts.generationNodes }} 个生成节点 · 1 张独立画布</p><ul><li v-for="mapping in preview.mappings" :key="mapping.slotKey">{{ mapping.label }}：{{ mapping.selection }}</li></ul><ul v-if="preview.media.length"><li v-for="file in preview.media" :key="file.key">{{ file.path }} · {{ Math.ceil(file.bytes / 1024) }} KB · 摘要 {{ file.hash.slice(0, 12) }}</li></ul><p v-for="warning in preview.warnings" :key="warning" class="hint">{{ warning }}</p><details v-if="preview.definition"><summary>核对填值后的镜头与参考内容</summary><productionTemplateDetail :definition="preview.definition" /></details><el-button v-if="!applied" type="primary" :loading="applying" :disabled="busy || !ready" @click="apply">确认创建独立制作单元</el-button></section>
        <section v-if="applied" role="status"><h3>制作模板已应用</h3><p>已保存 {{ applied.title }}，可以打开画布检查参考和模型，再逐镜头创作。</p><el-button type="primary" :disabled="busy" @click="openCanvas">打开新画布</el-button><el-button @click="emit('update:modelValue', false)">留在模板库</el-button></section>
      </template>
    </div>
  </el-dialog>
  <el-dialog v-model="fileDialog" title="选择目标项目中的参考文件" width="min(640px, 94vw)" appendToBody><div class="templateFileBrowser"><p>{{ filePath || '项目根目录' }}</p><el-button :disabled="fileLoading || !filePath" @click="listFiles(filePath.split('/').slice(0, -1).join('/'))">上一级</el-button><p v-if="fileError" role="alert">{{ fileError }}</p><p v-if="fileLoading" role="status">正在读取文件…</p><ul><li v-for="entry in visibleFiles" :key="entry.path"><button :disabled="fileLoading" @click="entry.type === 'directory' ? listFiles(entry.path) : selectFile(entry.path)">{{ entry.type === 'directory' ? '文件夹 · ' : '' }}{{ entry.name }}</button></li></ul><p v-if="!visibleFiles.length && !fileLoading">没有匹配的参考文件，可先将素材放入目标项目。</p></div></el-dialog>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";
import axios from "axios";
import { useRouter } from "vue-router";
import { ElMessageBox } from "element-plus";
import type { MediaModel } from "@toonflow/tools-scaffold/runtime";
import type { ProjectRecord } from "@toonflow/server/production";
import { templateMediaMimeTypes, type ProductionTemplate, type TemplateApplicationInput, type TemplatePreview } from "@toonflow/server/productionTemplates";
import workspacePicker from "@/pages/home/workspacePicker.vue";
import productionTemplateDetail from "./productionTemplateDetail.vue";
import useWorkspaceFiles from "@/lib/workspaceFiles";
import { useWorkspaceStore } from "@/stores/workspace";
import { productionTemplateError } from "@/stores/productionTemplates";
const props = defineProps<{ modelValue: boolean; definition?: ProductionTemplate }>();
const emit = defineEmits<{ "update:modelValue": [value: boolean] }>();
const workspace = useWorkspaceStore(); const router = useRouter(); const headers = { "x-toonflow-workspace": "1" }; const typeLabels = { image: "图片", video: "视频", audio: "音频" };
const directory = ref(""); const project = ref<ProjectRecord | null>(null); const models = ref<MediaModel[]>([]); const loading = ref(false); const ready = ref(false); const previewing = ref(false); const applying = ref(false); const busy = computed(() => applying.value || previewing.value);
const input = ref<TemplateApplicationInput>(); const selections = ref<Record<string, string>>({}); const preview = ref<TemplatePreview>(); const error = ref(""); const errorBox = ref<HTMLElement>(); const applied = ref<{ directory: string; canvasId: string; title: string }>(); const resuming = ref(false); const pending = ref<TemplateApplicationInput[]>([]); let epoch = 0;
function setInput(definition: ProductionTemplate) { input.value = { applicationId: crypto.randomUUID(), createdAt: Date.now(), definition: JSON.parse(JSON.stringify(definition)), values: Object.fromEntries(definition.inputs.map(item => [item.key, item.defaultValue])), mappings: [], mediaBindings: [] }; selections.value = Object.fromEntries(definition.modelSlots.map(slot => [slot.key, ""])); preview.value = undefined; applied.value = undefined; resuming.value = false; }
watch(() => props.modelValue, open => { if (!open) { ++epoch; return; } if (props.definition) setInput(props.definition); error.value = ""; directory.value = workspace.project?.directory ?? ""; void loadTarget(); });
watch(directory, (_path, previous) => { preview.value = undefined; applied.value = undefined; if (previous && input.value) { startIndependent(); input.value.mediaBindings = []; } if (props.modelValue) void loadTarget(); });
watch([input, selections], () => { preview.value = undefined; }, { deep: true, flush: "sync" });
async function fail(cause: unknown) { error.value = productionTemplateError(cause); await nextTick(); errorBox.value?.focus(); }
async function loadTarget() {
  const path = directory.value; const requestEpoch = ++epoch; ready.value = false; project.value = null; pending.value = []; preview.value = undefined; if (!path) return; loading.value = true;
  try { const [record, catalog, applications] = await Promise.all([axios.get<{ data: { project: ProjectRecord | null } }>("/api/production/get", { params: { directory: path }, headers }), axios.get<{ data: MediaModel[] }>("/api/ai/media/models"), axios.get<{ data: { items: TemplateApplicationInput[]; warnings: string[] } }>("/api/productionTemplates/pending", { params: { directory: path }, headers })]); if (requestEpoch !== epoch || path !== directory.value) return; project.value = record.data.data.project; models.value = catalog.data.data; pending.value = applications.data.data.items; error.value = applications.data.data.warnings.join("；"); ready.value = true; }
  catch (cause) { if (requestEpoch === epoch) await fail(cause); } finally { if (requestEpoch === epoch) loading.value = false; }
}
async function createProject() { const path = directory.value; applying.value = true; try { await axios.post("/api/production/create", { directory: path }, { headers }); if (path === directory.value) await loadTarget(); } catch (cause) { await fail(cause); } finally { applying.value = false; } }
function snapshot(): TemplateApplicationInput { if (!input.value) throw new Error("请重新打开模板"); const value = JSON.parse(JSON.stringify(input.value)) as TemplateApplicationInput; value.mappings = value.definition.modelSlots.map(slot => { const selection = selections.value[slot.key]; if (!selection) throw new Error(`请选择${slot.label}的实际模型，或明确选择稍后配置`); if (selection === "deferred") return { slotKey: slot.key, deferred: true }; const [providerId, modelId] = JSON.parse(selection) as [string, string]; return { slotKey: slot.key, deferred: false, providerId, modelId }; }); return value; }
async function previewApplication() { if (!project.value || busy.value) return; const path = directory.value; const revision = project.value.revision; previewing.value = true; error.value = ""; try { const value = snapshot(); const { data } = await axios.post<{ data: TemplatePreview }>("/api/productionTemplates/preview", { directory: path, expectedRevision: revision, input: value }, { headers }); if (path === directory.value && props.modelValue) preview.value = data.data; } catch (cause) { await fail(cause); } finally { previewing.value = false; } }
async function apply() { if (!preview.value || !project.value || busy.value) return; const path = directory.value; const pinned = preview.value; const value = snapshot(); applying.value = true; error.value = ""; try { const { data } = await axios.post<{ data: { project: ProjectRecord; resultId: string } }>("/api/production/update", { directory: path, expectedRevision: project.value.revision, operation: { type: "applyTemplate", ...value, previewFingerprint: pinned.previewFingerprint } }, { headers }); if (path !== directory.value) return; project.value = data.data.project; applied.value = { directory: path, canvasId: data.data.project.shots.find(shot => shot.sequenceId === data.data.resultId && shot.canvasId)?.canvasId ?? pinned.canvasId, title: pinned.title }; } catch (cause) { await fail(cause); } finally { applying.value = false; } }
function resume(value: TemplateApplicationInput) { input.value = JSON.parse(JSON.stringify(value)); selections.value = Object.fromEntries(value.mappings.map(item => [item.slotKey, item.deferred ? "deferred" : JSON.stringify([item.providerId, item.modelId])])); resuming.value = true; preview.value = undefined; applied.value = undefined; error.value = ""; }
function startIndependent() { if (!input.value) return; input.value.applicationId = crypto.randomUUID(); input.value.createdAt = Date.now(); resuming.value = false; }
async function openCanvas() { const result = applied.value; if (!result) return; applying.value = true; try { await workspace.openProject(result.directory); emit("update:modelValue", false); await router.push({ path: "/workspace", query: { canvas: result.canvasId } }); } catch (cause) { await fail(cause); } finally { applying.value = false; } }
async function closeDialog(done: () => void) { if (busy.value) return; if (input.value && !applied.value && !await ElMessageBox.confirm("关闭后本页填值将离开。已写入的待完成应用仍保留在目标项目。", "保留模板填值", { confirmButtonText: "继续填写", cancelButtonText: "关闭", distinguishCancelAndClose: true }).then(() => false, action => action === "cancel")) return; done(); }
const fileDialog = ref(false); const fileLoading = ref(false); const filePath = ref(""); const fileError = ref(""); const fileKey = ref(""); const fileDirectory = ref(""); const fileEntries = ref<{ name: string; path: string; type: "file" | "directory" }[]>([]);
function mime(path: string) { return templateMediaMimeTypes[path.split(".").at(-1)?.toLowerCase() ?? ""] ?? ""; }
const visibleFiles = computed(() => fileEntries.value.filter(entry => entry.type === "directory" ? !/^(projectBackups|productionTemplateInputs|productionTasks|productionBatches|projectImports|projectPackages)$/.test(entry.name) : mime(entry.path).startsWith(`${input.value?.definition.mediaInputs.find(item => item.key === fileKey.value)?.mediaType}/`)));
async function openFiles(key: string) { fileKey.value = key; fileDirectory.value = directory.value; fileDialog.value = true; await listFiles(""); }
async function listFiles(path: string) { const target = fileDirectory.value; fileLoading.value = true; fileError.value = ""; try { const result = await useWorkspaceFiles(target).list(path); if (target !== fileDirectory.value || !fileDialog.value) return; filePath.value = path; fileEntries.value = result.entries; } catch (cause) { fileError.value = productionTemplateError(cause); fileEntries.value = []; } finally { fileLoading.value = false; } }
function selectFile(path: string) { if (!input.value || directory.value !== fileDirectory.value) { fileError.value = "目标项目已切换，请重新选择文件"; return; } input.value.mediaBindings = [...input.value.mediaBindings.filter(item => item.key !== fileKey.value), { key: fileKey.value, path, mimeType: mime(path) }]; fileDialog.value = false; }
</script>

<style scoped lang="scss">
.templateApply { font-size: 13px; line-height: 1.8; overflow-wrap: anywhere; fieldset { min-width: 0; border: 0; padding: 0; margin: 0; } h3 { font-size: 15px; margin-top: 22px; } .targetRow { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; } .projectPath, .hint { font-size: 12px; color: var(--el-text-color-secondary); } .inputGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; } label { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; span { font-size: 12px; color: var(--el-text-color-secondary); } } textarea, select { width: 100%; min-width: 0; box-sizing: border-box; padding: 9px; border: 1px solid var(--el-border-color); color: var(--el-text-color-primary); background: var(--el-bg-color); font: inherit; border-radius: 6px; } .mediaBinding, .applicationPreview, .pendingApplications { border-top: 1px solid var(--el-border-color-light); padding-block: 14px; p { margin-block: 6px; } .el-button { margin: 6px 8px 6px 0; white-space: normal; height: auto; min-height: 36px; } } .errorText { color: var(--el-color-danger); padding-block: 8px; } :focus-visible { outline: 2px solid var(--el-color-primary); outline-offset: 2px; } @media(max-width:600px) { .inputGrid { grid-template-columns: 1fr; } .el-button, select { min-height: 44px; } } }
.templateFileBrowser { overflow-wrap: anywhere; ul { list-style: none; padding: 0; max-height: 45dvh; overflow: auto; } button:not(.el-button) { padding: 10px; width: 100%; min-height: 44px; text-align: left; color: var(--el-text-color-primary); background: var(--el-bg-color); border: 0; border-bottom: 1px solid var(--el-border-color-light); cursor: pointer; font: inherit; } :focus-visible { outline: 2px solid var(--el-color-primary); outline-offset: -2px; } }
</style>
